static bool parser_error(GrammarParser *parser,
                         const PbnfcLocation *location,
                         const char *detail)
{
    parser->failed = true;
    if (parser->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(parser->diagnostics, detail, location);
    }
    return false;
}

static bool parser_advance(GrammarParser *parser)
{
    if (!pbnfc_grammar_lexer_next(&parser->lexer, &parser->current)) {
        parser->failed = true;
        return false;
    }
    parser->have_current = true;
    return true;
}

static bool parser_expect(GrammarParser *parser,
                          PbnfcGrammarTokenKind kind,
                          const char *detail)
{
    if (!parser->have_current && !parser_advance(parser)) {
        return false;
    }
    if (parser->current.kind != kind) {
        return parser_error(parser, &parser->current.location, detail);
    }
    return true;
}

static bool append_start(PbnfcGrammar *grammar,
                         const PbnfcGrammarToken *token)
{
    size_t count;
    size_t bytes;
    PbnfcGrammarStartDirective *starts;
    char *name;

    if (!size_add_ok(grammar->start_count, 1U, &count) ||
        !size_mul_ok(count, sizeof(*starts), &bytes)) {
        return false;
    }
    name = copy_bytes(token->text, token->length);
    if (name == NULL) {
        return false;
    }
    starts = (PbnfcGrammarStartDirective *)realloc(grammar->starts, bytes);
    if (starts == NULL) {
        free(name);
        return false;
    }
    grammar->starts = starts;
    grammar->starts[grammar->start_count].name = name;
    grammar->starts[grammar->start_count].location = token->location;
    ++grammar->start_count;
    if (grammar->start_count == 1U) {
        grammar->start_name = grammar->starts[0].name;
    }
    return true;
}

static bool append_token_declaration(PbnfcGrammar *grammar,
                                     const PbnfcGrammarToken *token)
{
    size_t count;
    size_t bytes;
    PbnfcGrammarTokenDeclaration *declarations;
    char *name;

    if (!size_add_ok(grammar->token_declaration_count, 1U, &count) ||
        !size_mul_ok(count, sizeof(*declarations), &bytes)) {
        return false;
    }
    name = copy_bytes(token->text, token->length);
    if (name == NULL) {
        return false;
    }
    declarations = (PbnfcGrammarTokenDeclaration *)realloc(
        grammar->token_declarations, bytes);
    if (declarations == NULL) {
        free(name);
        return false;
    }
    grammar->token_declarations = declarations;
    grammar->token_declarations[grammar->token_declaration_count].name = name;
    grammar->token_declarations[grammar->token_declaration_count].location =
        token->location;
    ++grammar->token_declaration_count;
    return true;
}

static bool append_production(PbnfcGrammar *grammar,
                              const PbnfcGrammarToken *token,
                              PbnfcGrammarProduction **production)
{
    size_t count;
    size_t bytes;
    PbnfcGrammarProduction *productions;
    char *name;

    if (!size_add_ok(grammar->production_count, 1U, &count) ||
        !size_mul_ok(count, sizeof(*productions), &bytes)) {
        return false;
    }
    name = copy_bytes(token->text, token->length);
    if (name == NULL) {
        return false;
    }
    productions = (PbnfcGrammarProduction *)realloc(grammar->productions,
                                                     bytes);
    if (productions == NULL) {
        free(name);
        return false;
    }
    grammar->productions = productions;
    grammar->productions[grammar->production_count].name = name;
    grammar->productions[grammar->production_count].location = token->location;
    grammar->productions[grammar->production_count].alternatives = NULL;
    grammar->productions[grammar->production_count].alternative_count = 0U;
    *production = &grammar->productions[grammar->production_count];
    ++grammar->production_count;
    return true;
}

static bool append_alternative(PbnfcGrammarProduction *production,
                               PbnfcGrammarAlternative **alternative)
{
    size_t count;
    size_t bytes;
    PbnfcGrammarAlternative *alternatives;

    if (!size_add_ok(production->alternative_count, 1U, &count) ||
        !size_mul_ok(count, sizeof(*alternatives), &bytes)) {
        return false;
    }
    alternatives = (PbnfcGrammarAlternative *)realloc(
        production->alternatives, bytes);
    if (alternatives == NULL) {
        return false;
    }
    production->alternatives = alternatives;
    alternatives[production->alternative_count].symbols = NULL;
    alternatives[production->alternative_count].symbol_count = 0U;
    *alternative = &alternatives[production->alternative_count];
    ++production->alternative_count;
    return true;
}

static bool append_symbol(PbnfcGrammarAlternative *alternative,
                          const PbnfcGrammarToken *token)
{
    size_t count;
    size_t bytes;
    PbnfcGrammarSymbol *symbols;
    char *name;
    PbnfcGrammarSymbolKind kind;

    if (!size_add_ok(alternative->symbol_count, 1U, &count) ||
        !size_mul_ok(count, sizeof(*symbols), &bytes)) {
        return false;
    }
    if (token->kind == PBNFC_GRAMMAR_TOKEN_TERMINAL) {
        name = copy_terminal(token);
        kind = PBNFC_GRAMMAR_SYMBOL_TERMINAL;
    } else if (token->kind == PBNFC_GRAMMAR_TOKEN_REFERENCE) {
        name = copy_bytes(token->text + 1U, token->length - 1U);
        kind = PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE;
    } else {
        name = copy_bytes(token->text, token->length);
        kind = PBNFC_GRAMMAR_SYMBOL_NONTERMINAL;
    }
    if (name == NULL) {
        return false;
    }
    symbols = (PbnfcGrammarSymbol *)realloc(alternative->symbols, bytes);
    if (symbols == NULL) {
        free(name);
        return false;
    }
    alternative->symbols = symbols;
    symbols[alternative->symbol_count].kind = kind;
    symbols[alternative->symbol_count].name = name;
    symbols[alternative->symbol_count].location = token->location;
    ++alternative->symbol_count;
    return true;
}

static bool parse_start(GrammarParser *parser, PbnfcGrammar *grammar)
{
    if (!parser_advance(parser) ||
        !parser_expect(parser,
                       PBNFC_GRAMMAR_TOKEN_IDENTIFIER,
                       "expected start rule name")) {
        return false;
    }
    if (!append_start(grammar, &parser->current)) {
        return parser_error(parser, &parser->current.location,
                            "grammar AST allocation failed");
    }
    return parser_advance(parser);
}

static bool parse_token_declaration(GrammarParser *parser,
                                    PbnfcGrammar *grammar)
{
    if (!parser_advance(parser) ||
        !parser_expect(parser,
                       PBNFC_GRAMMAR_TOKEN_IDENTIFIER,
                       "expected token declaration name")) {
        return false;
    }
    if (!append_token_declaration(grammar, &parser->current)) {
        return parser_error(parser, &parser->current.location,
                            "grammar AST allocation failed");
    }
    return parser_advance(parser);
}

static bool is_symbol_token(PbnfcGrammarTokenKind kind)
{
    return kind == PBNFC_GRAMMAR_TOKEN_IDENTIFIER ||
           kind == PBNFC_GRAMMAR_TOKEN_TERMINAL ||
           kind == PBNFC_GRAMMAR_TOKEN_REFERENCE;
}

static bool parse_production(GrammarParser *parser,
                             PbnfcGrammar *grammar)
{
    PbnfcGrammarProduction *production;
    PbnfcGrammarAlternative *alternative;

    if (!append_production(grammar, &parser->current, &production)) {
        return parser_error(parser, &parser->current.location,
                            "grammar AST allocation failed");
    }
    if (!parser_advance(parser) ||
        !parser_expect(parser,
                       PBNFC_GRAMMAR_TOKEN_ASSIGN,
                       "expected ::= after production name")) {
        return false;
    }
    if (!parser_advance(parser)) {
        return false;
    }

    for (;;) {
        if (!append_alternative(production, &alternative)) {
            return parser_error(parser, &parser->current.location,
                                "grammar AST allocation failed");
        }
        while (is_symbol_token(parser->current.kind)) {
            if (!append_symbol(alternative, &parser->current)) {
                return parser_error(parser, &parser->current.location,
                                    "grammar AST allocation failed");
            }
            if (!parser_advance(parser)) {
                return false;
            }
        }
        if (parser->current.kind == PBNFC_GRAMMAR_TOKEN_SEMICOLON) {
            return parser_advance(parser);
        }
        if (parser->current.kind != PBNFC_GRAMMAR_TOKEN_PIPE) {
            return parser_error(parser, &parser->current.location,
                                "expected | or ; after production alternative");
        }
        if (!parser_advance(parser)) {
            return false;
        }
    }
}

static bool parse_source(GrammarParser *parser, PbnfcGrammar *grammar)
{
    bool saw_production = false;

    if (!parser_advance(parser)) {
        return false;
    }
    while (parser->current.kind != PBNFC_GRAMMAR_TOKEN_EOF) {
        if (parser->current.kind == PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE) {
            if (saw_production) {
                return parser_error(parser, &parser->current.location,
                                    "directives must precede productions");
            }
            if (!parse_start(parser, grammar)) {
                return false;
            }
        } else if (parser->current.kind == PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE) {
            if (saw_production) {
                return parser_error(parser, &parser->current.location,
                                    "directives must precede productions");
            }
            if (!parse_token_declaration(parser, grammar)) {
                return false;
            }
        } else if (parser->current.kind == PBNFC_GRAMMAR_TOKEN_IDENTIFIER) {
            saw_production = true;
            if (!parse_production(parser, grammar)) {
                return false;
            }
        } else {
            return parser_error(parser, &parser->current.location,
                                "expected grammar directive or production");
        }
    }
    return true;
}

bool pbnfc_grammar_parse(const char *source,
                         size_t length,
                         const PbnfcDiagnosticContext *diagnostics,
                         PbnfcGrammar **grammar_out)
{
    GrammarParser parser;
    PbnfcGrammar *grammar;

    if (grammar_out == NULL) {
        return false;
    }
    *grammar_out = NULL;
    grammar = (PbnfcGrammar *)calloc(1U, sizeof(*grammar));
    if (grammar == NULL) {
        if (diagnostics != NULL) {
            (void)pbnfc_diagnostic_emit(diagnostics,
                                        "grammar AST allocation failed",
                                        NULL);
        }
        return false;
    }
    (void)memset(&parser, 0, sizeof(parser));
    parser.diagnostics = diagnostics;
    pbnfc_grammar_lexer_init(&parser.lexer, source, length, diagnostics);
    if (!parse_source(&parser, grammar) || parser.failed) {
        pbnfc_grammar_free(grammar);
        return false;
    }
    *grammar_out = grammar;
    return true;
}
#ifndef PBNFC_GRAMMAR_LEXER_H
#define PBNFC_GRAMMAR_LEXER_H

#include "diagnostics.h"

#include <stdbool.h>
#include <stddef.h>

typedef enum {
    PBNFC_GRAMMAR_TOKEN_EOF = 0,
    PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE,
    PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE,
    PBNFC_GRAMMAR_TOKEN_IDENTIFIER,
    PBNFC_GRAMMAR_TOKEN_TERMINAL,
    PBNFC_GRAMMAR_TOKEN_REFERENCE,
    PBNFC_GRAMMAR_TOKEN_ASSIGN,
    PBNFC_GRAMMAR_TOKEN_PIPE,
    PBNFC_GRAMMAR_TOKEN_SEMICOLON
} PbnfcGrammarTokenKind;

/*
 * A token is a non-owning view into the source buffer supplied to the lexer.
 * The caller owns that buffer and must keep it alive while using the token.
 */
typedef struct {
    PbnfcGrammarTokenKind kind;
    PbnfcLocation location;
    const char *text;
    size_t length;
} PbnfcGrammarToken;

typedef struct {
    const char *source;
    size_t length;
    size_t offset;
    size_t line;
    size_t column;
    const PbnfcDiagnosticContext *diagnostics;
    bool failed;
} PbnfcGrammarLexer;

void pbnfc_grammar_lexer_init(PbnfcGrammarLexer *lexer,
                              const char *source,
                              size_t length,
                              const PbnfcDiagnosticContext *diagnostics);

/* Returns true for every token, including EOF, and false after a lexing error. */
bool pbnfc_grammar_lexer_next(PbnfcGrammarLexer *lexer,
                               PbnfcGrammarToken *token);

bool pbnfc_grammar_lexer_failed(const PbnfcGrammarLexer *lexer);

const char *pbnfc_grammar_token_kind_name(PbnfcGrammarTokenKind kind);

#endif
#include "grammar_lexer.h"

#include <stddef.h>

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9');
}

static bool is_ignored_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static unsigned char current_character(const PbnfcGrammarLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcGrammarLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_ignored(PbnfcGrammarLexer *lexer)
{
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (is_ignored_space(character)) {
            advance_one(lexer);
        } else if (character == (unsigned char)'#') {
            while (lexer->offset < lexer->length &&
                   current_character(lexer) != (unsigned char)'\n') {
                advance_one(lexer);
            }
        } else {
            break;
        }
    }
}

static bool has_text(const PbnfcGrammarLexer *lexer,
                     size_t offset,
                     const char *text,
                     size_t length)
{
    size_t index;

    if (offset > lexer->length || length > lexer->length - offset) {
        return false;
    }
    for (index = 0U; index < length; ++index) {
        if (lexer->source[offset + index] != text[index]) {
            return false;
        }
    }
    return true;
}

static bool emit_error(PbnfcGrammarLexer *lexer,
                       const PbnfcLocation *location,
                       const char *detail)
{
    lexer->failed = true;
    if (lexer->diagnostics != NULL) {
        (void)pbnfc_diagnostic_emit(lexer->diagnostics, detail, location);
    }
    return false;
}

static void set_token(PbnfcGrammarToken *token,
                      PbnfcGrammarTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool read_directive(PbnfcGrammarLexer *lexer,
                           PbnfcGrammarToken *token,
                           PbnfcLocation location)
{
    size_t start = lexer->offset;
    size_t length;
    PbnfcGrammarTokenKind kind;

    if (has_text(lexer, start, "%start", 6U)) {
        length = 6U;
        kind = PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE;
    } else if (has_text(lexer, start, "%token", 6U)) {
        length = 6U;
        kind = PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE;
    } else {
        return emit_error(lexer, &location, "unknown grammar directive");
    }

    if (start + length < lexer->length &&
        is_identifier_part((unsigned char)lexer->source[start + length])) {
        return emit_error(lexer, &location, "malformed grammar directive");
    }

    while (length > 0U) {
        advance_one(lexer);
        --length;
    }
    set_token(token,
              kind,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

static bool read_identifier(PbnfcGrammarLexer *lexer,
                            PbnfcGrammarToken *token,
                            PbnfcLocation location)
{
    size_t start = lexer->offset;

    while (lexer->offset < lexer->length &&
           is_identifier_part(current_character(lexer))) {
        advance_one(lexer);
    }
    set_token(token,
              PBNFC_GRAMMAR_TOKEN_IDENTIFIER,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

static bool read_terminal(PbnfcGrammarLexer *lexer,
                          PbnfcGrammarToken *token,
                          PbnfcLocation location)
{
    size_t start = lexer->offset;

    /* Keep the complete source lexeme, including quotes and escape pairs. */
    advance_one(lexer);
    while (lexer->offset < lexer->length) {
        unsigned char character = current_character(lexer);

        if (character == (unsigned char)'\'') {
            advance_one(lexer);
            set_token(token,
                      PBNFC_GRAMMAR_TOKEN_TERMINAL,
                      location,
                      lexer->source + start,
                      lexer->offset - start);
            return true;
        }
        if (character == (unsigned char)'\n' ||
            character == (unsigned char)'\r') {
            return emit_error(lexer, &location, "unterminated grammar terminal");
        }
        if (character == (unsigned char)'\\') {
            advance_one(lexer);
            if (lexer->offset == lexer->length ||
                (current_character(lexer) != (unsigned char)'\'' &&
                 current_character(lexer) != (unsigned char)'\\')) {
                return emit_error(lexer, &location, "invalid grammar terminal escape");
            }
        }
        advance_one(lexer);
    }

    return emit_error(lexer, &location, "unterminated grammar terminal");
}

static bool read_reference(PbnfcGrammarLexer *lexer,
                           PbnfcGrammarToken *token,
                           PbnfcLocation location)
{
    size_t start = lexer->offset;

    advance_one(lexer);
    if (lexer->offset == lexer->length ||
        !is_identifier_start(current_character(lexer))) {
        return emit_error(lexer, &location, "malformed grammar token reference");
    }
    while (lexer->offset < lexer->length &&
           is_identifier_part(current_character(lexer))) {
        advance_one(lexer);
    }
    set_token(token,
              PBNFC_GRAMMAR_TOKEN_REFERENCE,
              location,
              lexer->source + start,
              lexer->offset - start);
    return true;
}

void pbnfc_grammar_lexer_init(PbnfcGrammarLexer *lexer,
                              const char *source,
                              size_t length,
                              const PbnfcDiagnosticContext *diagnostics)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->diagnostics = diagnostics;
    lexer->failed = source == NULL && length != 0U;
}

bool pbnfc_grammar_lexer_next(PbnfcGrammarLexer *lexer,
                               PbnfcGrammarToken *token)
{
    PbnfcLocation location;
    size_t start;

    if (lexer == NULL || token == NULL || lexer->failed) {
        return false;
    }
    if (lexer->source == NULL && lexer->length != 0U) {
        return emit_error(lexer, NULL, "grammar source is unavailable");
    }

    skip_ignored(lexer);
    location.byte_offset = lexer->offset;
    location.line = lexer->line;
    location.column = lexer->column;
    start = lexer->offset;

    if (lexer->offset == lexer->length) {
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_EOF,
                  location,
                  lexer->source == NULL ? NULL : lexer->source + start,
                  0U);
        return true;
    }

    switch (current_character(lexer)) {
    case (unsigned char)'%':
        return read_directive(lexer, token, location);
    case (unsigned char)':':
        if (!has_text(lexer, start, "::=", 3U)) {
            return emit_error(lexer, &location, "expected ::= punctuation");
        }
        advance_one(lexer);
        advance_one(lexer);
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_ASSIGN,
                  location,
                  lexer->source + start,
                  3U);
        return true;
    case (unsigned char)'|':
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_PIPE,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    case (unsigned char)';':
        advance_one(lexer);
        set_token(token,
                  PBNFC_GRAMMAR_TOKEN_SEMICOLON,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    case (unsigned char)'\'':
        return read_terminal(lexer, token, location);
    case (unsigned char)'$':
        return read_reference(lexer, token, location);
    default:
        if (is_identifier_start(current_character(lexer))) {
            return read_identifier(lexer, token, location);
        }
        return emit_error(lexer, &location, "invalid character in grammar");
    }
}

bool pbnfc_grammar_lexer_failed(const PbnfcGrammarLexer *lexer)
{
    return lexer == NULL || lexer->failed;
}

const char *pbnfc_grammar_token_kind_name(PbnfcGrammarTokenKind kind)
{
    switch (kind) {
    case PBNFC_GRAMMAR_TOKEN_EOF:
        return "eof";
    case PBNFC_GRAMMAR_TOKEN_START_DIRECTIVE:
        return "%start";
    case PBNFC_GRAMMAR_TOKEN_TOKEN_DIRECTIVE:
        return "%token";
    case PBNFC_GRAMMAR_TOKEN_IDENTIFIER:
        return "identifier";
    case PBNFC_GRAMMAR_TOKEN_TERMINAL:
        return "terminal";
    case PBNFC_GRAMMAR_TOKEN_REFERENCE:
        return "token-reference";
    case PBNFC_GRAMMAR_TOKEN_ASSIGN:
        return "::=";
    case PBNFC_GRAMMAR_TOKEN_PIPE:
        return "|";
    case PBNFC_GRAMMAR_TOKEN_SEMICOLON:
        return ";";
    }
    return "unknown";
}
