    nullable = (bool *)calloc(1U, bytes);
    if (nullable == NULL) {
        return validation_error(diagnostics,
                                earliest_location(grammar),
                                "grammar validation allocation failed");
    }
    if (!size_mul_ok(grammar->production_count,
                     sizeof(*stack),
                     &bytes)) {
        free(nullable);
        return validation_error(diagnostics,
                                earliest_location(grammar),
                                "grammar validation allocation failed");
    }
    if (!size_mul_ok(grammar->production_count,
                     sizeof(*visited),
                     &bytes)) {
        free(nullable);
        return validation_error(diagnostics,
                                earliest_location(grammar),
                                "grammar validation allocation failed");
    }
    visited = (bool *)calloc(1U, bytes);
    stack = (size_t *)malloc(bytes);
    if (visited == NULL || stack == NULL) {
        free(visited);
        free(stack);
        free(nullable);
        return validation_error(diagnostics,
                                earliest_location(grammar),
                                "grammar validation allocation failed");
    }

    compute_nullable_productions(grammar, nullable);
    for (index = 0U; index < grammar->production_count; ++index) {
        const PbnfcLocation *location = NULL;

        if (find_left_recursion_from(grammar,
                                     nullable,
                                     index,
                                     visited,
                                     stack,
                                     &location)) {
            free(visited);
            free(stack);
            free(nullable);
            return validation_error(diagnostics,
                                    location,
                                    location,
                                    "left recursion detected");
        }
    }
    free(visited);
    free(stack);
    free(nullable);
    return true;
}

